import{_ as t,o as r,c as n,a2 as d}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Index der Rechtsvorschriften","description":"","frontmatter":{},"headers":[],"relativePath":"de/92-法律条文索引.md","filePath":"de/92-法律条文索引.md","lastUpdated":1789183869000}'),s={name:"de/92-法律条文索引.md"};function i(a,e,u,h,l,g){return r(),n("div",null,[...e[0]||(e[0]=[d('<h1 id="index-der-rechtsvorschriften" tabindex="-1">Index der Rechtsvorschriften <a class="header-anchor" href="#index-der-rechtsvorschriften" aria-label="Permalink to &quot;Index der Rechtsvorschriften&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Punkt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>92</td></tr><tr><td>Modul</td><td>Anhänge und Referenzmaterialien</td></tr><tr><td>Schlüsselwörter</td><td>Rechtsindex, Verfassung der Symbiose, Arbeitsgesetz, Verbraucherschutzgesetz, Begleitgesetze</td></tr></tbody></table><h2 id="_1-beschreibung-des-index" tabindex="-1">1. Beschreibung des Index <a class="header-anchor" href="#_1-beschreibung-des-index" aria-label="Permalink to &quot;1. Beschreibung des Index&quot;">​</a></h2><p>Dieser Index enthält die wichtigsten derzeit geltenden Rechtsdokumente und ihre Kernbestimmungen der Anker-Symbiose-Zivilisation, geordnet nach Rechtshierarchie und Abteilung. Der Geltungsbereich des Index umfasst die &quot;Verfassung der Symbiose&quot;, das &quot;Arbeitsgesetz der Symbiose&quot;, das &quot;Verbraucherschutzgesetz&quot; sowie fünf Begleitgesetze zu Bildung, Gesundheit, Wohnen, Umwelt und Kartellverbot. Jeder Indexeintrag listet den Gesetzesnamen, die Artikelnummer und eine Zusammenfassung des Kerninhalts des Artikels auf. Dieser Index ist ein Referenzwerkzeug; für den vollständigen Text der Rechtsvorschriften und gerichtlichen Auslegungen konsultieren Sie bitte den offiziellen Text jedes Gesetzes.</p><h2 id="_2-verfassung-der-symbiose" tabindex="-1">2. Verfassung der Symbiose <a class="header-anchor" href="#_2-verfassung-der-symbiose" aria-label="Permalink to &quot;2. Verfassung der Symbiose&quot;">​</a></h2><p>Die &quot;Verfassung der Symbiose&quot; ist das Grundgesetz der Anker-Symbiose-Zivilisation mit höchster Rechtskraft, erlassen bei der formellen Gründung der Symbiose-Zivilisation.</p><table tabindex="0"><thead><tr><th>Artikelnummer</th><th>Kerninhalt</th></tr></thead><tbody><tr><td>Artikel 1</td><td>Legt Hengyuanzhou (Ursprungsuniversum Wanling Hengmao) als Herrschaftsgebiet der Anker-Symbiose-Zivilisation fest; der grundlegende Zweck der Symbiose-Zivilisation ist die Erreichung der Symbiose aller Rassen und der kosmischen Dimensionserhöhung</td></tr><tr><td>Artikel 2</td><td>Legt den Anti-Plünderismus als grundlegende Haltung der Zivilisation fest; verbietet jede Form von Plünderungs-Kultivierung und Ressourcenplünderung</td></tr><tr><td>Artikel 3</td><td>Legt &quot;die Rückgabe des Rechts auf Schicksals- und Evolutionswahl an alle fühlenden Wesen&quot; als Kernkonzept der Zivilisation fest</td></tr><tr><td>Artikel 4</td><td>Legt Mehrarbeit-Mehrertrag, Selbstwachstum, Jeder hat einen Weg, Alle Rassen schreiten gemeinsam voran als Grundrichtlinien der Zivilisation fest</td></tr><tr><td>Artikel 5</td><td>Legt das System der kostenlosen Öffnung von dreihundert Sätzen von Ursprungs-Kultivierungssystemen fest; keine Organisation oder Person darf die Übertragungsgenehmigung von Kultivierungssystemen monopolisieren</td></tr><tr><td>Artikel 6</td><td>Legt den Mechanismus des gemeinsamen Produktionsvertrags als grundlegendes Ressourcenverteilungssystem fest</td></tr><tr><td>Artikel 7</td><td>Legt die 20%-Aktivierungsstrategie als stufiges nationales Ziel fest</td></tr><tr><td>Artikel 8</td><td>Legt den Grundsatz der Realitätsbezogenheit fest; die reale Welt ist die einzige reale Welt, fiktive Einstellungen haben keine Rechtskraft</td></tr><tr><td>Artikel 9</td><td>Legt den vierstufigen Pfad der Dimensionserhöhung als langfristige Entwicklungsstrategie der Zivilisation fest</td></tr><tr><td>Artikel 10</td><td>Legt den Grundsatz der Gleichheit aller Rassen fest; alle Lebensformen sind vor dem Gesetz gleich</td></tr><tr><td>Artikel 11</td><td>Legt den Grundsatz der symbiotischen Evolution fest; die individuelle Evolution darf nicht auf Kosten der Beeinträchtigung der Evolutionsrechte anderer Individuen oder Kollektive erfolgen</td></tr><tr><td>Artikel 12</td><td>Legt den Grundsatz Mehrarbeit-Mehrertrag fest; die Ressourcenverteilung nimmt den Beitrag als zentrale Grundlage</td></tr><tr><td>Artikel 13</td><td>Legt den Grundsatz des Selbstwachstums fest; respektiert das Recht jedes Lebens, die Evolution autonom zu wählen</td></tr><tr><td>Artikel 14</td><td>Legt den Grundsatz Jeder hat einen Weg fest; der Staat ist verpflichtet, jedem Leben einen grundlegenden Evolutionspfad und Ressourcengarantie zu gewähren</td></tr><tr><td>Artikel 15</td><td>Legt den Grundsatz der Nachhaltigkeit fest; alle Entwicklungen müssen die Nachhaltigkeit des kosmischen Ursprungs berücksichtigen</td></tr><tr><td>Artikel 16-25</td><td>Legen die Grundrechte aller fühlenden Wesen fest: Recht auf Evolutionswahl, Recht auf Erhalt von Kultivierungsressourcen, Recht auf gleichen Schutz, Recht auf symbiotische Teilhabe, Recht auf Kulturerhaltung, Recht auf Hilfe und Berufung, Recht auf persönliche Freiheit, Recht auf Menschenwürde, Recht auf Glaubensfreiheit, Recht auf Meinungsfreiheit</td></tr><tr><td>Artikel 26-31</td><td>Legen die Grundpflichten aller fühlenden Wesen fest: Pflicht zur Gesetzesbefolgung, Pflicht zur Aufrechterhaltung der symbiotischen Ordnung, Pflicht zur Arbeitsbeitragung, Pflicht zum Umweltschutz, Pflicht zur Achtung der Rechte anderer, Pflicht zur Anleitung nachrangiger Kultivierer</td></tr><tr><td>Artikel 32</td><td>Legt den Anker-Rat als höchste Gewalt fest, zusammengesetzt aus Vertretern aller Rassen anteilig</td></tr><tr><td>Artikel 33</td><td>Legt das Exekutivkomitee der Symbiose als höchstes Verwaltungsorgan fest</td></tr><tr><td>Artikel 34</td><td>Legt das Gericht der Symbiose als höchstes Justizorgan fest, das die Justizgewalt unabhängig ausübt</td></tr><tr><td>Artikel 35</td><td>Legt das Anker-Aufsichtskomitee als unabhängiges Aufsichtsorgan fest</td></tr><tr><td>Artikel 36</td><td>Legt das Gesetzgebungsverfahren fest: Gesetzesvorlagen werden mit einer Mehrheit von mehr als der Hälfte des Anker-Rats verabschiedet</td></tr><tr><td>Artikel 37</td><td>Legt das Verfahren zur Verfassungsänderung fest: muss mit einer Mehrheit von mehr als zwei Dritteln des Anker-Rats verabschiedet und von mehr als der Hälfte des nationalen Referendums gebilligt werden</td></tr><tr><td>Artikel 38</td><td>Legt das System der verfassungsgerichtlichen Kontrolle fest; das Gericht der Symbiose hat das Recht, Gesetze, die gegen die Verfassung verstoßen, für ungültig zu erklären</td></tr><tr><td>Artikel 39</td><td>Legt das System der Verfassungsbeschwerde fest; alle fühlenden Wesen können direkt Klage auf Grundlage der Verfassung erheben</td></tr><tr><td>Artikel 40</td><td>Legt das System der lokalen Autonomie fest; jedes Sternendomäne und jede Ebene führt Autonomie im Rahmen der Verfassung durch</td></tr><tr><td>Artikel 41</td><td>Legt das Republiksystem aller Rassen fest; alle ethnischen Gruppen sind in der Symbiose-Zivilisation gleich und führen regionale Autonomie durch</td></tr><tr><td>Artikel 42</td><td>Legt das Wirtschaftssystem der Symbiose-Zivilisation fest: basierend auf gemeinsamen Produktionsverträgen entwickeln sich mehrere Eigentumswirtschaften gemeinsam</td></tr><tr><td>Artikel 43</td><td>Legt das System des Staatseigentums und der gerechten Verteilung von Kultivierungsressourcen fest</td></tr><tr><td>Artikel 44</td><td>Legt das System der Bildungsgerechtigkeit fest, gewährleistet das Recht jedes Lebens auf gleiche Bildung</td></tr><tr><td>Artikel 45</td><td>Legt das System der universellen medizinischen Versorgung fest</td></tr><tr><td>Artikel 46</td><td>Legt das System der Wohnversorgung fest, gewährleistet das grundlegende Wohnrecht jedes Lebens</td></tr><tr><td>Artikel 47</td><td>Legt die Grundsätze der Interaktion zwischen Ebenen fest; keine unerlaubte Reise zwischen Ebenen ohne Genehmigung</td></tr><tr><td>Artikel 48</td><td>Legt fest, dass die legitime Produktion archäologischer Aktivitäten auf abstraktes Wissen und Informationen beschränkt ist; die Rückführung von Materie und Energie ist verboten</td></tr><tr><td>Artikel 49</td><td>Legt die Grundsätze der Zeitrückverfolgung fest; muss dem Grundsatz zuerst Beobachtung, dann begrenzte Intervention folgen</td></tr><tr><td>Artikel 50</td><td>Legt fest, dass das Recht auf Auslegung der Verfassung dem Gericht der Symbiose zusteht, und das Recht auf Änderung der Verfassung dem Anker-Rat zusteht</td></tr></tbody></table><h2 id="_3-arbeitsgesetz-der-symbiose" tabindex="-1">3. Arbeitsgesetz der Symbiose <a class="header-anchor" href="#_3-arbeitsgesetz-der-symbiose" aria-label="Permalink to &quot;3. Arbeitsgesetz der Symbiose&quot;">​</a></h2><p>Das &quot;Arbeitsgesetz der Symbiose&quot; ist das Grundgesetz zur Regelung der Arbeitsbeziehungen und zum Schutz der Rechte und Interessen der Arbeitnehmer, mit Artikel 42 der Verfassung der Symbiose als legislativer Grundlage.</p><table tabindex="0"><thead><tr><th>Artikelnummer</th><th>Kerninhalt</th></tr></thead><tbody><tr><td>Artikel 1</td><td>Gesetzgebungszweck: Regelung der Arbeitsbeziehungen, Schutz der legitimen Rechte und Interessen der Arbeitnehmer und Aufbau harmonischer und symbiotischer Arbeitsbeziehungen</td></tr><tr><td>Artikel 2</td><td>Geltungsbereich: alle Arbeitsbeziehungen innerhalb von Hengyuanzhou, einschließlich materieller Arbeit, Kultivierungsarbeit und kreativer Arbeit</td></tr><tr><td>Artikel 3</td><td>Legt den Grundsatz der gleichen Beschäftigung für Arbeitnehmer fest; verbietet Beschäftigungsdiskriminierung aufgrund von Rasse, Geschlecht, Kultivierungsniveau oder Herkunft</td></tr><tr><td>Artikel 4</td><td>Legt den Grundsatz der freien Berufswahl für Arbeitnehmer fest; verbietet Zwangsarbeit und Sklaverei</td></tr><tr><td>Artikel 5</td><td>Legt das System des Arbeitsvertrags fest; bei Begründung eines Arbeitsverhältnisses muss ein schriftlicher Arbeitsvertrag abgeschlossen werden</td></tr><tr><td>Artikel 6</td><td>Legt die erforderlichen Klauseln des Arbeitsvertrags fest: Vertragslaufzeit, Arbeitsinhalt, Arbeitsentgelt, Arbeitszeit, Arbeitsschutz, Sozialversicherung</td></tr><tr><td>Artikel 7</td><td>Legt das Acht-Stunden-Arbeitssystem und das System der Arbeitszeit von nicht mehr als vierundvierzig Stunden pro Woche fest</td></tr><tr><td>Artikel 8</td><td>Legt Überstundenbeschränkungen fest: tägliche Überstunden dürfen eine Stunde nicht überschreiten, besondere Umstände drei Stunden nicht, monatliche Überstunden sechsunddreißig Stunden nicht</td></tr><tr><td>Artikel 9</td><td>Legt die Standards für Überstundenvergütung fest: 1,5-faches Entgelt für Überstunden an Werktagen, 2-faches Entgelt für Überstunden an Ruhetagen, 3-faches Entgelt für Überstunden an gesetzlichen Feiertagen</td></tr><tr><td>Artikel 10</td><td>Legt das System der Mindestlohngarantie fest; die Mindestlohnstandards werden von jeder Sternendomäne entsprechend den örtlichen Gegebenheiten festgelegt</td></tr><tr><td>Artikel 11</td><td>Legt das System der Lohnzahlung fest; Löhne müssen monatlich an den Arbeitnehmer selbst in Geldform gezahlt werden und dürfen nicht unbegründet einbehalten oder verzögert werden</td></tr><tr><td>Artikel 12</td><td>Legt den Verteilungsgrundsatz Mehrarbeit-Mehrertrag fest; implementiert ein Verteilungssystem mit der Verteilung nach Arbeit als Hauptkörper und mehreren Verteilungsmethoden nebeneinander</td></tr><tr><td>Artikel 13</td><td>Legt das System der Arbeitssicherheit und des Gesundheitsschutzes fest; Arbeitgeber müssen den Arbeitnehmern den Standards entsprechende Arbeitssicherheits- und Gesundheitsbedingungen gewähren</td></tr><tr><td>Artikel 14</td><td>Legt den Schutz besonderer Gruppen fest: besonderer Arbeitsschutz für minderjährige Arbeitnehmer, weibliche Arbeitnehmer, behinderte Arbeitnehmer und niedrig kultivierte Arbeitnehmer</td></tr><tr><td>Artikel 15</td><td>Legt das System der Berufsausbildung fest; Arbeitgeber sind verpflichtet, für Arbeitnehmer eine Berufsausbildung durchzuführen</td></tr><tr><td>Artikel 16</td><td>Legt die Arbeitsrechte und -interessen von Kultivierern fest: Kultivierungsarbeit wird ebenfalls durch dieses Gesetz geschützt; das Eigentum an Kultivierungsergebnissen wird vertraglich vereinbart</td></tr><tr><td>Artikel 17</td><td>Legt das System der Sozialversicherung der Arbeitnehmer fest: Rentenversicherung, Krankenversicherung, Arbeitslosenversicherung, Unfallversicherung, Mutterschaftsversicherung</td></tr><tr><td>Artikel 18</td><td>Legt das System der Arbeitnehmerfürsorge fest; Arbeitgeber müssen den Arbeitnehmern die erforderlichen Sozialleistungen gewähren</td></tr><tr><td>Artikel 19</td><td>Legt das System der Arbeitsstreitbeilegung fest: vierstufiger Beilegungsmechanismus aus Verhandlung, Vermittlung, Schiedsspruch und Gerichtsverfahren</td></tr><tr><td>Artikel 20</td><td>Legt das System der Gewerkschaften fest; Arbeitnehmer haben das Recht, Gewerkschaften gemäß Gesetz zu gründen und ihnen beizutreten, um ihre legitimen Rechte und Interessen zu wahren</td></tr><tr><td>Artikel 21</td><td>Legt das System des Tarifvertrags fest; Gewerkschaften vertreten die Arbeitnehmer beim Abschluss von Tarifverträgen mit den Arbeitgebern</td></tr><tr><td>Artikel 22</td><td>Legt fest, dass die Regeln und Vorschriften der Arbeitgeber von der Arbeitnehmervertretungsversammlung oder allen Arbeitnehmern erörtert werden müssen</td></tr><tr><td>Artikel 23</td><td>Legt die Bedingungen und Verfahren für die Beendigung von Arbeitsverträgen fest</td></tr><tr><td>Artikel 24</td><td>Legt das System der wirtschaftlichen Entschädigung fest; Arbeitgeber müssen bei Beendigung von Arbeitsverträgen gemäß Gesetz eine wirtschaftliche Entschädigung zahlen</td></tr><tr><td>Artikel 25</td><td>Legt das System der Entschädigung für rechtswidrige Beendigung von Arbeitsverträgen fest</td></tr><tr><td>Artikel 26</td><td>Legt das System der Verwaltung von Arbeitskräfteüberlassung fest, regelt die Beschäftigung durch Arbeitskräfteüberlassung</td></tr><tr><td>Artikel 27</td><td>Legt besondere Regeln für Teilzeitbeschäftigung fest</td></tr><tr><td>Artikel 28</td><td>Legt das System der Aufsicht und Prüfung fest; die Arbeitsverwaltungsabteilungen beaufsichtigen und prüfen gemäß Gesetz die Einhaltung der Arbeitsgesetze und -vorschriften durch die Arbeitgeber</td></tr><tr><td>Artikel 29</td><td>Legt die rechtliche Verantwortung fest: Arbeitgeber, die gegen dieses Gesetz verstoßen, übernehmen gemäß Gesetz administrative, zivilrechtliche und strafrechtliche Verantwortung</td></tr><tr><td>Artikel 30</td><td>Legt das Inkrafttreten und das Auslegungsrecht dieses Gesetzes fest</td></tr></tbody></table><h2 id="_4-verbraucherschutzgesetz" tabindex="-1">4. Verbraucherschutzgesetz <a class="header-anchor" href="#_4-verbraucherschutzgesetz" aria-label="Permalink to &quot;4. Verbraucherschutzgesetz&quot;">​</a></h2><p>Das &quot;Verbraucherschutzgesetz&quot; ist das Grundgesetz zum Schutz der legitimen Rechte und Interessen der Verbraucher und zur Regelung des Verhaltens von Unternehmern.</p><table tabindex="0"><thead><tr><th>Artikelnummer</th><th>Kerninhalt</th></tr></thead><tbody><tr><td>Artikel 1</td><td>Gesetzgebungszweck: Schutz der legitimen Rechte und Interessen der Verbraucher, Aufrechterhaltung der sozialen und wirtschaftlichen Ordnung und Förderung der gesunden Entwicklung der symbiotischen Marktwirtschaft</td></tr><tr><td>Artikel 2</td><td>Geltungsbereich: Schutz der Rechte und Interessen von Verbrauchern innerhalb von Hengyuanzhou, die Waren für den täglichen Bedarf kaufen, nutzen oder Dienstleistungen erhalten</td></tr><tr><td>Artikel 3</td><td>Legt die Grundsätze für Transaktionen zwischen Unternehmern und Verbrauchern fest: Freiwilligkeit, Gleichheit, Fairness, Ehrlichkeit und Glaubwürdigkeit</td></tr><tr><td>Artikel 4</td><td>Legt den Grundsatz des staatlichen Schutzes der legitimen Rechte und Interessen der Verbraucher fest; der Staat ergreift Maßnahmen, um sicherzustellen, dass die Verbraucher ihre Rechte gemäß Gesetz ausüben</td></tr><tr><td>Artikel 5</td><td>Legt neun Grundrechte der Verbraucher fest: Recht auf Sicherheit, Recht auf Information, Recht auf freie Wahl, Recht auf faire Transaktion, Recht auf Entschädigung, Recht auf Vereinigung, Recht auf Wissenserwerb, Recht auf Respekt, Recht auf Aufsicht</td></tr><tr><td>Artikel 6</td><td>Legt das Recht auf Sicherheit der Verbraucher fest: Verbraucher genießen das Recht, dass persönliche und Vermögenssicherheit beim Kauf, der Nutzung von Waren und dem Erhalt von Dienstleistungen nicht beeinträchtigt wird</td></tr><tr><td>Artikel 7</td><td>Legt das Recht auf Information der Verbraucher fest: Verbraucher genießen das Recht, die tatsächliche Situation der von ihnen gekauften oder genutzten Waren oder der erhaltenen Dienstleistungen zu kennen</td></tr><tr><td>Artikel 8</td><td>Legt das Recht auf freie Wahl der Verbraucher fest: Verbraucher genießen das Recht, Waren oder Dienstleistungen frei zu wählen</td></tr><tr><td>Artikel 9</td><td>Legt das Recht auf faire Transaktion der Verbraucher fest: Verbraucher genießen das Recht auf faire Transaktion und haben das Recht, erzwungene Transaktionsverhalten abzulehnen</td></tr><tr><td>Artikel 10</td><td>Legt das Recht auf Entschädigung der Verbraucher fest: Verbraucher, die durch den Kauf, die Nutzung von Waren oder den Erhalt von Dienstleistungen persönliche oder Vermögensschäden erleiden, genießen das Recht, gemäß Gesetz Entschädigung zu erhalten</td></tr><tr><td>Artikel 11</td><td>Legt die Grundpflichten der Unternehmer fest: Erfüllung gesetzlicher und vertraglicher Pflichten, Annahme von Aufsicht, Gewährleistung der Sicherheit, Bereitstellung wahrheitsgemäßer Informationen, Ausstellung von Belegen, Gewährleistung der Qualität, Erfüllung der drei Garantien, keine unlautere Transaktion, keine Persönlichkeitsverletzung</td></tr><tr><td>Artikel 12</td><td>Legt die Pflicht zur Sicherstellung der Sicherheit der Unternehmer fest: Unternehmer müssen sicherstellen, dass die von ihnen bereitgestellten Waren oder Dienstleistungen den Anforderungen des Schutzes der persönlichen und Vermögenssicherheit entsprechen</td></tr><tr><td>Artikel 13</td><td>Legt die Pflicht zur Offenlegung von Informationen der Unternehmer fest: Unternehmer müssen den Verbrauchern wahrheitsgemäße Informationen über Waren oder Dienstleistungen bereitstellen und dürfen keine falsche oder irreführende Werbung machen</td></tr><tr><td>Artikel 14</td><td>Legt besondere Normen für Kultivierungswaren und -dienstleistungen fest: Unternehmer von Kultivierungsmethoden, Kultivierungsinstrumenten und Energiewaren müssen über besondere Qualifikationen verfügen, und die Waren müssen die Sicherheitszertifizierung bestehen</td></tr><tr><td>Artikel 15</td><td>Legt die Regelung von Allgemeinen Geschäftsbedingungen fest; Unternehmer dürfen durch Allgemeine Geschäftsbedingungen nicht die Rechte der Verbraucher ausschließen oder einschränken, die Verantwortung der Unternehmer verringern oder befreien</td></tr><tr><td>Artikel 16</td><td>Legt das System der siebentägigen rückgabefreien Rückgabe fest; Verbraucher, die Waren über Fernwege wie das Internet kaufen, haben das Recht, die Waren innerhalb von sieben Tagen ab Erhalt der Waren zurückzugeben</td></tr><tr><td>Artikel 17</td><td>Legt das System der drei Garantien fest; wenn die von Unternehmern bereitgestellten Waren oder Dienstleistungen nicht den Qualitätsanforderungen entsprechen, können Verbraucher gemäß staatlichen Vorschriften Reparatur, Austausch oder Rückgabe verlangen</td></tr><tr><td>Artikel 18</td><td>Legt das System der Strafentschädigung fest; wenn Unternehmer bei der Bereitstellung von Waren oder Dienstleistungen betrügerisches Verhalten aufweisen, müssen sie gemäß den Anforderungen der Verbraucher die Entschädigung für den erlittenen Schaden der Verbraucher erhöhen, und der Betrag der erhöhten Entschädigung muss das Dreifache des Preises der von den Verbrauchern gekauften Waren oder der Kosten der erhaltenen Dienstleistungen betragen</td></tr><tr><td>Artikel 19</td><td>Legt Verbraucherorganisationen fest; Verbraucherverbände und andere Verbraucherorganisationen sind gemäß Gesetz gegründete soziale Organisationen, die soziale Aufsicht über Waren und Dienstleistungen zum Schutz der legitimen Rechte und Interessen der Verbraucher ausüben</td></tr><tr><td>Artikel 20</td><td>Legt die Kanäle zur Beilegung von Verbraucherstreitigkeiten fest: Verhandlung und Vergleich mit Unternehmern, Antrag auf Vermittlung durch den Verbraucherverband, Beschwerde bei den zuständigen Verwaltungsabteilungen, Antrag auf Schiedsspruch, Erhebung einer Klage beim Gericht</td></tr><tr><td>Artikel 21</td><td>Legt die Umkehr der Beweislast bei Streitigkeiten fest; bei langlebigen Waren oder Dienstleistungen wie Dekoration, wenn Verbraucher innerhalb von sechs Monaten ab Annahme Mängel feststellen, trägt der Unternehmer die Beweislast</td></tr><tr><td>Artikel 22</td><td>Legt die administrative und strafrechtliche Verantwortung der Unternehmer fest</td></tr><tr><td>Artikel 23</td><td>Legt das Inkrafttreten und das Auslegungsrecht dieses Gesetzes fest</td></tr></tbody></table><h2 id="_5-funf-begleitgesetze" tabindex="-1">5. Fünf Begleitgesetze <a class="header-anchor" href="#_5-funf-begleitgesetze" aria-label="Permalink to &quot;5. Fünf Begleitgesetze&quot;">​</a></h2><h3 id="_5-1-gesetz-zur-bildungsversorgung" tabindex="-1">5.1 Gesetz zur Bildungsversorgung <a class="header-anchor" href="#_5-1-gesetz-zur-bildungsversorgung" aria-label="Permalink to &quot;5.1 Gesetz zur Bildungsversorgung&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Artikelnummer</th><th>Kerninhalt</th></tr></thead><tbody><tr><td>Artikel 1</td><td>Gesetzgebungszweck: Gewährleistung des Rechts auf gleiche Bildung für alle fühlenden Wesen, Aufbau eines symbiotischen Bildungssystems und Förderung der gemeinsamen Entwicklung der Kulturen aller Rassen</td></tr><tr><td>Artikel 2-5</td><td>Legen den Grundsatz der Bildungsgerechtigkeit, den Grundsatz der gebührenfreien Bildung (Grundbildungsstufe), den Grundsatz der Bildungsvielfalt, den Grundsatz der Bildungsinnovation fest</td></tr><tr><td>Artikel 6-10</td><td>Legen die Architektur des Systems der Vorschulbildung, Pflichtbildung, Oberstufenbildung, Hochschulbildung, Kultivierungsbildung fest</td></tr><tr><td>Artikel 11-15</td><td>Legen besondere Systeme für die Kultivierungsbildung fest: Lehrnormen für dreihundert Sätze von Systemen, Mentorsystem, System der Ressourcenzuweisung für Kultivierung</td></tr><tr><td>Artikel 16-20</td><td>Legen die Rechte und Pflichten der Lehrer, das System der Lehrerqualifikation, die Garantie der Lehrerbehandlung fest</td></tr><tr><td>Artikel 21-25</td><td>Legen die Garantie der Bildungsinvestition, den Bau von Bildungseinrichtungen, die Bildungsinformatisierung, die Sonderpädagogik, die interrassische Bildung fest</td></tr><tr><td>Artikel 26-30</td><td>Legen das System der Bildungsbewertung, das System der Bildungsaufsicht, die rechtliche Verantwortung und die Zusatzbestimmungen fest</td></tr></tbody></table><h3 id="_5-2-gesetz-zur-medizinischen-versorgung" tabindex="-1">5.2 Gesetz zur medizinischen Versorgung <a class="header-anchor" href="#_5-2-gesetz-zur-medizinischen-versorgung" aria-label="Permalink to &quot;5.2 Gesetz zur medizinischen Versorgung&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Artikelnummer</th><th>Kerninhalt</th></tr></thead><tbody><tr><td>Artikel 1</td><td>Gesetzgebungszweck: Aufbau eines universellen medizinischen Versorgungssystems, Gewährleistung des Rechts auf Gesundheit für alle fühlenden Wesen und Verbesserung des allgemeinen Gesundheitsniveaus aller Rassen</td></tr><tr><td>Artikel 2-5</td><td>Legen den Grundsatz der universellen Krankenversicherung, den Grundsatz der gebührenfreien Grundmedizin, den Grundsatz der Integration chinesischer und westlicher Medizin, den Grundsatz der Einbeziehung der Kultivierungsmedizin fest</td></tr><tr><td>Artikel 6-10</td><td>Legen das mehrstufige Krankenversicherungssystem aus Grundkrankenversicherung, Schwerkrankversicherung, medizinischer Hilfe, kommerzieller Krankenversicherung fest</td></tr><tr><td>Artikel 11-15</td><td>Legen die Verwaltung medizinischer Einrichtungen, das System des medizinischen Personals, die medizinische Qualität und Sicherheit, besondere Normen für die Kultivierungsmedizin fest</td></tr><tr><td>Artikel 16-20</td><td>Legen die Arzneimittelverwaltung, die Verwaltung medizinischer Geräte, die Verwaltung medizinischer Energieprodukte, das System der unentbehrlichen Arzneimittel fest</td></tr><tr><td>Artikel 21-25</td><td>Legen das System der öffentlichen Gesundheit, die Prävention und Kontrolle von Krankheiten, die Gesundheitserziehung, die interrassische Medizin, die medizinische Versorgung besonderer Gruppen fest</td></tr><tr><td>Artikel 26-30</td><td>Legen die Beilegung medizinischer Streitigkeiten, die medizinische Aufsicht, die rechtliche Verantwortung und die Zusatzbestimmungen fest</td></tr></tbody></table><h3 id="_5-3-gesetz-zur-wohnversorgung" tabindex="-1">5.3 Gesetz zur Wohnversorgung <a class="header-anchor" href="#_5-3-gesetz-zur-wohnversorgung" aria-label="Permalink to &quot;5.3 Gesetz zur Wohnversorgung&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Artikelnummer</th><th>Kerninhalt</th></tr></thead><tbody><tr><td>Artikel 1</td><td>Gesetzgebungszweck: Gewährleistung des grundlegenden Wohnrechts aller fühlenden Wesen, Aufbau eines mehrstufigen Wohnversorgungssystems und Erreichung von Wohnen für alle</td></tr><tr><td>Artikel 2-5</td><td>Legen den Grundsatz der Garantie des Wohnrechts, den Grundsatz der Wohngerechtigkeit, den Grundsatz der gleichzeitigen Miete und des Kaufs, den Grundsatz des nachhaltigen Wohnens fest</td></tr><tr><td>Artikel 6-10</td><td>Legen das Wohnversorgungssystem aus öffentlichem Mietwohnraum, sozialem Mietwohnraum, gemeinsamem Eigentumswohnraum, gewerblichem Wohnraum fest</td></tr><tr><td>Artikel 11-15</td><td>Legen das System der Wohnbaukasse, das System des Wohngelds, die Unterstützungsrichtlinie für Erstwohnungen, die besondere Wohnrichtlinie für Kultivierer fest</td></tr><tr><td>Artikel 16-20</td><td>Legen die Normen für den Wohnungsbau, die Anwendung der Weltraumtechnologie im Wohnen, grüne Gebäude, altersgerechtes und barrierefreies Wohnen fest</td></tr><tr><td>Artikel 21-25</td><td>Legen die Regulierung des Immobilienmarktes, die Regulierung des Wohnungsmarktes, die Verwaltung von Immobiliendienstleistungen, die Garantie der Wohnungsinstandhaltung fest</td></tr><tr><td>Artikel 26-30</td><td>Legen die Aufsicht über die Wohnversorgung, die rechtliche Verantwortung und die Zusatzbestimmungen fest</td></tr></tbody></table><h3 id="_5-4-umweltschutzgesetz" tabindex="-1">5.4 Umweltschutzgesetz <a class="header-anchor" href="#_5-4-umweltschutzgesetz" aria-label="Permalink to &quot;5.4 Umweltschutzgesetz&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Artikelnummer</th><th>Kerninhalt</th></tr></thead><tbody><tr><td>Artikel 1</td><td>Gesetzgebungszweck: Schutz und Verbesserung der Umwelt, Prävention und Kontrolle von Umweltverschmutzung und anderen öffentlichen Gefahren, Gewährleistung der öffentlichen Gesundheit, Förderung des Aufbaus einer kosmischen ökologischen Zivilisation und Förderung der nachhaltigen Entwicklung</td></tr><tr><td>Artikel 2-5</td><td>Legen den Grundsatz des Vorrangs des Schutzes, den Grundsatz der Prävention zuerst, den Grundsatz der umfassenden Behandlung, den Grundsatz der öffentlichen Beteiligung, den Grundsatz der Verantwortung des Verursachers fest</td></tr><tr><td>Artikel 6-10</td><td>Legen das System der Umweltschutzaufsicht und -verwaltung, das System der Umweltnormen, das System der Umweltverträglichkeitsprüfung, das System der Umweltüberwachung, die Umweltverwaltung zwischen Ebenen fest</td></tr><tr><td>Artikel 11-15</td><td>Legen die Prävention und Kontrolle der Luftverschmutzung, der Wasserverschmutzung, der Bodenverschmutzung, der Energieverschmutzung, der Gesetzesverschmutzung fest</td></tr><tr><td>Artikel 16-20</td><td>Legen die Behandlung von festen Abfällen, die Prävention und Kontrolle der Lärmbelastung, der radioaktiven Verschmutzung, den ökologischen Schutz, den Schutz der biologischen Vielfalt fest</td></tr><tr><td>Artikel 21-25</td><td>Legen die Kontrolle der Umweltauswirkungen von Kultivierungsaktivitäten, den ökologischen Schutz des Energiebergbaus, die Umweltanforderungen für die Archäologie zwischen Ebenen fest</td></tr><tr><td>Artikel 26-30</td><td>Legen die Informationsoffenlegung und öffentliche Beteiligung, die Umweltklage im öffentlichen Interesse, die rechtliche Verantwortung und die Zusatzbestimmungen fest</td></tr></tbody></table><h3 id="_5-5-kartellverbotgesetz" tabindex="-1">5.5 Kartellverbotgesetz <a class="header-anchor" href="#_5-5-kartellverbotgesetz" aria-label="Permalink to &quot;5.5 Kartellverbotgesetz&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Artikelnummer</th><th>Kerninhalt</th></tr></thead><tbody><tr><td>Artikel 1</td><td>Gesetzgebungszweck: Prävention und Bekämpfung von monopolistischem Verhalten, Schutz des fairen Wettbewerbs auf dem Markt, Verbesserung der Effizienz des Wirtschaftsbetriebs, Wahrung der Verbraucherinteressen und des sozialen öffentlichen Interesses sowie Förderung der gesunden Entwicklung der symbiotischen Marktwirtschaft</td></tr><tr><td>Artikel 2-5</td><td>Legen die grundlegende Haltung der Wettbewerbspolitik, das System der Prüfung auf fairen Wettbewerb, das Verbot von Monopolvereinbarungen, das Verbot des Missbrauchs einer marktbeherrschenden Stellung, die Kontrolle von Unternehmenszusammenschlüssen fest</td></tr><tr><td>Artikel 6-10</td><td>Legen die Feststellung und Freistellung von Monopolvereinbarungen, horizontale Monopolvereinbarungen, vertikale Monopolvereinbarungen, monopolistisches Verhalten von Industrieverbänden fest</td></tr><tr><td>Artikel 11-15</td><td>Legen die Feststellung einer marktbeherrschenden Stellung, die Arten des missbräuchlichen Verhaltens einer marktbeherrschenden Stellung, das Verbot von räuberischer Preisgestaltung fest</td></tr><tr><td>Artikel 16-20</td><td>Legen die Anmeldestandards für Unternehmenszusammenschlüsse, das Prüfverfahren, zusätzliche einschränkende Bedingungen, die Entscheidung zum Verbot eines Zusammenschlusses fest</td></tr><tr><td>Artikel 21-25</td><td>Legen das besondere Verbot des Monopols von Kultivierungssystemen fest: Verbot der Monopolisierung von Kultivierungsmethoden, Verbot des Monopols von Kultivierungsressourcen, Verbot des Monopols von Mentorennetzwerken</td></tr><tr><td>Artikel 26-30</td><td>Legen die Kartellverfolgungsbehörden, das Untersuchungsverfahren, die rechtliche Verantwortung, das System der Nachsicht und die Zusatzbestimmungen fest</td></tr></tbody></table><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Der Index der Rechtsvorschriften ist eine Referenzkarte des Rechtstaatssystems der Anker-Symbiose-Zivilisation. Von der Verfassung der Symbiose als Grundgesetz über das Arbeitsgesetz und das Verbraucherschutzgesetz zur Regelung des Lebens der Menschen bis hin zu den fünf Begleitgesetzen bilden sie gemeinsam ein vollständiges Rechtssystem &quot;mit der Verfassung als Oberbefehlshaber, den Grundgesetzen als Rückgrat und den Begleitgesetzen als Unterstützung&quot;. Dieses System gewährleistet, dass alle Aktivitäten der Symbiose-Zivilisation auf dem Pfad des Rechtstaates operieren, und bietet eine solide institutionelle Garantie für den gemeinsamen Fortschritt aller Rassen.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>40-Grundriß der Verfassung der Symbiose</li><li>41-Arbeitsgesetz der Symbiose</li><li>48-Justizsystem und Gerichtsmechanismus</li></ul>',28)])])}const b=t(s,[["render",i]]);export{c as __pageData,b as default};
